    url: `${SUPABASE_URL}/rest/v1/content_calendar?platform=eq.instagram&status=eq.ready&order=id.asc&limit=20`,
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`
    },
    json: true
  });

  if (Array.isArray(respSup) && respSup.length > 0) {
    // Filtra itens que NÃO batem com tópicos bloqueados e são do tipo desejado
    const candidatosValidos = respSup.filter(r => {
      try {
        const meta = typeof r.content_id === 'string' ? JSON.parse(r.content_id) : r.content_id;
        const tipoItem = meta.tipo || 'curiosidade';
        const cap = (r.caption || '').toLowerCase();
        const temaId = (meta.tema_id || '').toLowerCase();

        // Checagem anti-repetição rígida
        for (const bloq of topicosBloqueados) {
          if (temaId.includes(bloq) || cap.includes(bloq)) return false;
        }

        return tipoItem === tipoDesejado || (!isPostVenda && tipoItem === 'curiosidade');
      } catch (e) {
        return false;
      }
    });

    if (candidatosValidos.length > 0) {
      itemFila = candidatosValidos[0];
    }
  }
} catch (e) {}

let criativo = null;
let itemDbId = null;

if (itemFila) {
  itemDbId = itemFila.id;
  try {
    const meta = typeof itemFila.content_id === 'string' ? JSON.parse(itemFila.content_id) : itemFila.content_id;
    criativo = {
      formato: meta.format || 'carrossel',
      slides: meta.slides || [itemFila.media_url],
      story_url: meta.story_url,
      caption: itemFila.caption,
      tema_id: meta.tema_id || 'inedito',
      tipo: meta.tipo || tipoDesejado
    };
  } catch (errParse) {
    criativo = {
      formato: 'single_card',
      slides: [itemFila.media_url],
      caption: itemFila.caption,
      tipo: tipoDesejado
    };
  }
} else {
  // ROTAÇÃO DINÂMICA NO POOL DE DIVERSIDADE (Exclui estritamente tópicos bloqueados)
  const poolBase = isPostVenda ? POOL_DIVERSIDADE_VENDAS : POOL_DIVERSIDADE_CURIOSIDADES;
  const poolFiltrado = poolBase.filter(item => !topicosBloqueados.has(item.topico_chave));
  const poolFinal = poolFiltrado.length > 0 ? poolFiltrado : poolBase;

  const idxSorteado = (dia + hora) % poolFinal.length;
  criativo = poolFinal[idxSorteado];
}

// =============================================================================
// 4. PUBLICAR NO INSTAGRAM FEED (CARROSSEL OU CARD ÚNICO)
// =============================================================================
let feedPostId = null;

if (criativo.formato === 'carrossel' && criativo.slides && criativo.slides.length >= 2) {
  const childIds = [];
  for (let i = 0; i < criativo.slides.length; i++) {
    try {
      const resChild = await this.helpers.httpRequest({
        method: 'POST',
        url: `https://graph.instagram.com/v21.0/${INSTAGRAM_ACCOUNT_ID}/media`,
        body: {
          image_url: criativo.slides[i],
          is_carousel_item: 'true',
          access_token: INSTAGRAM_ACCESS_TOKEN
        },
        json: true
      });
      if (resChild && resChild.id) {
        childIds.push(resChild.id);
      }
    } catch (errChild) {}
  }

  if (childIds.length >= 2) {
    try {
      const resParent = await this.helpers.httpRequest({
        method: 'POST',
        url: `https://graph.instagram.com/v21.0/${INSTAGRAM_ACCOUNT_ID}/media`,
        body: {
          media_type: 'CAROUSEL',
          children: childIds.join(','),
          caption: criativo.caption,
          access_token: INSTAGRAM_ACCESS_TOKEN
        },
        json: true
      });

      if (resParent && resParent.id) {
        await new Promise(r => setTimeout(r, 6000));
        const resPub = await this.helpers.httpRequest({
          method: 'POST',
          url: `https://graph.instagram.com/v21.0/${INSTAGRAM_ACCOUNT_ID}/media_publish`,
          body: {
            creation_id: resParent.id,
            access_token: INSTAGRAM_ACCESS_TOKEN
          },
          json: true
        });
        if (resPub && resPub.id) {
          feedPostId = resPub.id;
        }
      }
    } catch (errParent) {}
  }
} else {
  try {
    const resCard = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://graph.instagram.com/v21.0/${INSTAGRAM_ACCOUNT_ID}/media`,
      body: {
        image_url: criativo.slides[0],
        caption: criativo.caption,
        access_token: INSTAGRAM_ACCESS_TOKEN
      },
      json: true
    });

    if (resCard && resCard.id) {
      await new Promise(r => setTimeout(r, 5000));
      const resPub = await this.helpers.httpRequest({
        method: 'POST',
        url: `https://graph.instagram.com/v21.0/${INSTAGRAM_ACCOUNT_ID}/media_publish`,
        body: {
          creation_id: resCard.id,
          access_token: INSTAGRAM_ACCESS_TOKEN
        },
        json: true
      });
      if (resPub && resPub.id) {
        feedPostId = resPub.id;
      }
    }
  } catch (errCard) {}
}

// =============================================================================
// 5. PUBLICAR STORY CORRESPONDENTE SE DISPONÍVEL
// =============================================================================
let storyPostId = null;
if (criativo.story_url) {
  try {
    const resStory = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://graph.instagram.com/v21.0/${INSTAGRAM_ACCOUNT_ID}/media`,
      body: {
        media_type: 'STORIES',
        image_url: criativo.story_url,
        access_token: INSTAGRAM_ACCESS_TOKEN
      },
      json: true
    });
    if (resStory && resStory.id) {
      await new Promise(r => setTimeout(r, 5000));
      const resPubStory = await this.helpers.httpRequest({
        method: 'POST',
        url: `https://graph.instagram.com/v21.0/${INSTAGRAM_ACCOUNT_ID}/media_publish`,
        body: {
          creation_id: resStory.id,
          access_token: INSTAGRAM_ACCESS_TOKEN
        },
        json: true
      });
      if (resPubStory && resPubStory.id) {
        storyPostId = resPubStory.id;
      }
    }
  } catch (errStory) {}
}

// =============================================================================
// 6. PUBLICAR SIMULTANEAMENTE NA PÁGINA DO FACEBOOK (MARCÃO PERSONAL)
// =============================================================================
let fbPostId = null;
try {
  if (criativo.slides && criativo.slides.length > 0) {
    const resFb = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://graph.facebook.com/v21.0/${FACEBOOK_PAGE_ID}/photos`,
      body: {
        url: criativo.slides[0],
        caption: criativo.caption,
        access_token: FACEBOOK_PAGE_TOKEN
      },
      json: true
    });
    if (resFb && (resFb.post_id || resFb.id)) {
      fbPostId = resFb.post_id || resFb.id;
    }
  }
} catch (errFb) {}

// =============================================================================
// 7. ATUALIZAR STATUS NO SUPABASE COM CABEÇALHOS CORRETOS (PREFER: RETURN=MINIMAL)
// =============================================================================
if (itemDbId && feedPostId) {
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${SUPABASE_URL}/rest/v1/content_calendar?id=eq.${itemDbId}`,
      headers: {
        'apikey': SUPABASE_KEY,
        'Authorization': `Bearer ${SUPABASE_KEY}`,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal'
      },
      body: {
        status: 'published',
        published_at: new Date().toISOString()
      },
      json: true
    });
  } catch (errPatch) {}
}

return [{
  json: {
    sucesso: Boolean(feedPostId),
    post_id: feedPostId,
    story_id: storyPostId,
    facebook_id: fbPostId,
    formato: criativo.formato,
    tipo: criativo.tipo,
    tema_id: criativo.tema_id,
    topicos_bloqueados: Array.from(topicosBloqueados),
    timestamp: new Date().toISOString()
  }
}];
